const paginasHttp = $input.all();
const paginasOrigen = $('Start').first().json.Split_Out_allItems;

const empresaBase = $('Start').first().json._firstItem;
const empresa = empresaBase.empresa || "NO IDENTIFICADO";


// ============================================================
// FUNCIONES
// ============================================================

function limpiarEspacios(texto) {
  return String(texto || "")
    .replace(/\s+/g, " ")
    .trim();
}

function decodificarHtml(texto) {
  return String(texto || "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&#(\d+);/g, (_, n) => {
      try {
        return String.fromCharCode(Number(n));
      } catch {
        return "";
      }
    });
}

function htmlATexto(html) {
  return limpiarEspacios(
    decodificarHtml(
      String(html || "")
        .replace(/<script[\s\S]*?<\/script>/gi, " ")
        .replace(/<style[\s\S]*?<\/style>/gi, " ")
        .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ")
        .replace(/<svg[\s\S]*?<\/svg>/gi, " ")
        .replace(/<!--[\s\S]*?-->/g, " ")
        .replace(/<br\s*\/?>/gi, " ")
        .replace(/<\/p>/gi, " ")
        .replace(/<\/div>/gi, " ")
        .replace(/<\/li>/gi, " ")
        .replace(/<[^>]+>/g, " ")
    )
  );
}

function normalizarTelefono(valor) {
  const original = String(valor || "").trim();

  let limpio = original
    .replace(/^tel:/i, "")
    .replace(/^phone:/i, "")
    .trim();

  const tieneMas = limpio.startsWith("+");
  const digitos = limpio.replace(/\D/g, "");

  if (digitos.length < 7 || digitos.length > 15) {
    return null;
  }

  return tieneMas
    ? `+${digitos}`
    : digitos;
}

function unicos(lista) {
  return [...new Set(
    lista
      .filter(Boolean)
      .map(x => String(x).trim())
  )];
}

function obtenerTitulo(html) {
  const match = String(html || "")
    .match(/<title[^>]*>([\s\S]*?)<\/title>/i);

  return match
    ? limpiarEspacios(decodificarHtml(match[1]))
    : "";
}

function extraerEmails(html, texto) {
  const encontrados = [];

  // mailto: es la señal más fuerte
  const mailto =
    /href\s*=\s*["']mailto:([^"'?]+)[^"']*["']/gi;

  let m;

  while ((m = mailto.exec(html)) !== null) {
    encontrados.push(
      String(m[1]).trim().toLowerCase()
    );
  }

  // Correos visibles en la página
  const regexEmail =
    /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi;

  const visibles =
    String(texto || "").match(regexEmail) || [];

  encontrados.push(
    ...visibles.map(x =>
      x
        .replace(/[),.;:]+$/g, "")
        .toLowerCase()
    )
  );

  return unicos(encontrados);
}

function extraerTelefonosTel(html) {
  const telefonos = [];

  const regex =
    /href\s*=\s*["']tel:([^"']+)["']/gi;

  let m;

  while ((m = regex.exec(html)) !== null) {
    const tel = normalizarTelefono(m[1]);

    if (tel) {
      telefonos.push(tel);
    }
  }

  return unicos(telefonos);
}

function extraerWhatsapps(html) {
  const whatsapps = [];

  const patrones = [
    /https?:\/\/wa\.me\/(\d+)/gi,
    /https?:\/\/api\.whatsapp\.com\/send\?[^"']*phone=(\d+)/gi,
    /https?:\/\/(?:www\.)?whatsapp\.com\/send\?[^"']*phone=(\d+)/gi
  ];

  for (const regex of patrones) {
    let m;

    while ((m = regex.exec(html)) !== null) {
      const numero =
        normalizarTelefono(m[1]);

      if (numero) {
        whatsapps.push(numero);
      }
    }
  }

  return unicos(whatsapps);
}

function extraerLinksSociales(html) {
  const links = {
    linkedin: [],
    facebook: [],
    instagram: [],
    youtube: [],
    x_twitter: []
  };

  const regex =
    /href\s*=\s*["'](https?:\/\/[^"']+)["']/gi;

  let m;

  while ((m = regex.exec(html)) !== null) {
    const url =
      decodificarHtml(m[1]).trim();

    const low = url.toLowerCase();

    if (low.includes("linkedin.com")) {
      links.linkedin.push(url);
    }

    if (low.includes("facebook.com")) {
      links.facebook.push(url);
    }

    if (low.includes("instagram.com")) {
      links.instagram.push(url);
    }

    if (low.includes("youtube.com") ||
        low.includes("youtu.be")) {
      links.youtube.push(url);
    }

    if (low.includes("twitter.com") ||
        low.includes("x.com")) {
      links.x_twitter.push(url);
    }
  }

  for (const key of Object.keys(links)) {
    links[key] = unicos(links[key]);
  }

  return links;
}


// ============================================================
// EXTRAER FRAGMENTOS IMPORTANTES
// ============================================================

function obtenerFragmentos(texto) {

  const palabras = [
    "correo",
    "email",
    "teléfono",
    "telefono",
    "whatsapp",
    "contacto",
    "trabaja con nosotros",
    "talento",
    "recursos humanos",
    "selección",
    "seleccion",
    "colaboradores",
    "empleados",
    "quiénes somos",
    "quienes somos",
    "ecuador",
    "quito",
    "guayaquil"
  ];

  const textoLower =
    texto.toLowerCase();

  const fragmentos = [];

  for (const palabra of palabras) {

    let posicion =
      textoLower.indexOf(palabra);

    while (posicion >= 0) {

      const inicio =
        Math.max(0, posicion - 250);

      const fin =
        Math.min(
          texto.length,
          posicion + palabra.length + 450
        );

      fragmentos.push(
        limpiarEspacios(
          texto.slice(inicio, fin)
        )
      );

      posicion =
        textoLower.indexOf(
          palabra,
          posicion + palabra.length
        );
    }
  }

  return unicos(fragmentos)
    .slice(0, 15);
}


// ============================================================
// PROCESAR LAS PÁGINAS
// ============================================================

const paginasProcesadas = [];

for (let i = 0; i < paginasHttp.length; i++) {

  const respuesta =
    paginasHttp[i]?.json || {};

  const origen =
    paginasOrigen[i]?.json
      ?.urls_para_verificar || {};

  const html =
    String(respuesta.data || "");

  if (!html) {
    continue;
  }

  const texto =
    htmlATexto(html);

  const titulo =
    obtenerTitulo(html) ||
    origen.titulo ||
    "";

  const emails =
    extraerEmails(html, texto);

  const telefonos =
    extraerTelefonosTel(html);

  const whatsapps =
    extraerWhatsapps(html);

  const redes =
    extraerLinksSociales(html);

  const fragmentos =
    obtenerFragmentos(texto);

  paginasProcesadas.push({

    url:
      origen.url || "NO IDENTIFICADA",

    dominio:
      origen.dominio || "NO IDENTIFICADO",

    titulo,

    emails,

    telefonos,

    whatsapps,

    redes_sociales:
      redes,

    fragmentos_relevantes:
      fragmentos,

    texto_limpio_muestra:
      texto.slice(0, 5000)
  });
}


// ============================================================
// CONSOLIDAR CONTACTOS
// ============================================================

const emailsConFuente = [];
const telefonosConFuente = [];
const whatsappsConFuente = [];

for (const pagina of paginasProcesadas) {

  for (const email of pagina.emails) {

    emailsConFuente.push({
      email,
      fuente: pagina.url,
      dominio: pagina.dominio
    });
  }

  for (const telefono of pagina.telefonos) {

    telefonosConFuente.push({
      telefono,
      fuente: pagina.url,
      dominio: pagina.dominio
    });
  }

  for (const whatsapp of pagina.whatsapps) {

    whatsappsConFuente.push({
      whatsapp,
      fuente: pagina.url,
      dominio: pagina.dominio
    });
  }
}


// ============================================================
// ELIMINAR DUPLICADOS CONSERVANDO FUENTE
// ============================================================

function deduplicarPor(lista, campo) {

  const vistos = new Set();
  const salida = [];

  for (const item of lista) {

    const valor =
      String(item[campo] || "").toLowerCase();

    if (!valor || vistos.has(valor)) {
      continue;
    }

    vistos.add(valor);
    salida.push(item);
  }

  return salida;
}


// ============================================================
// DETECTAR POSIBLE NÚMERO DE COLABORADORES
// SIN INVENTAR
// ============================================================

const candidatosColaboradores = [];

for (const pagina of paginasProcesadas) {

  const fragmentos =
    pagina.fragmentos_relevantes || [];

  for (const fragmento of fragmentos) {

    if (
      /colaboradores|empleados/i.test(
        fragmento
      )
    ) {

      candidatosColaboradores.push({
        texto: fragmento,
        fuente: pagina.url
      });
    }
  }
}


// ============================================================
// RESULTADO FINAL
// ============================================================

return [
  {
    json: {

      empresa,

      estado:
        "PAGINAS_OFICIALES_PROCESADAS",

      total_paginas_procesadas:
        paginasProcesadas.length,

      emails_oficiales:
        deduplicarPor(
          emailsConFuente,
          "email"
        ),

      telefonos_oficiales:
        deduplicarPor(
          telefonosConFuente,
          "telefono"
        ),

      whatsapp_oficiales:
        deduplicarPor(
          whatsappsConFuente,
          "whatsapp"
        ),

      candidatos_numero_colaboradores:
        candidatosColaboradores
          .slice(0, 10),

      paginas:
        paginasProcesadas,

      siguiente_accion:
        "ANALIZAR_EMPRESA_Y_BUSCAR_PERSONA_CONTACTO"
    }
  }
];

const busqueda = $input.first().json;
const contexto = $("Edit Fields3").first().json;

const empresa = contexto.empresa || "NO IDENTIFICADO";

const resultados = Array.isArray(busqueda.results)
  ? busqueda.results
  : [];


// ============================================================
// 1. FUNCIONES GENERALES
// ============================================================

function limpiar(texto) {
  return String(texto || "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizar(texto) {
  return limpiar(texto)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}


// ============================================================
// 2. EXTRAER DOMINIO SIN USAR new URL()
// ============================================================

function dominioDe(url) {

  let texto = String(url || "")
    .trim()
    .toLowerCase();

  texto = texto
    .replace(/^https?:\/\//, "")
    .replace(/^www\./, "");

  texto = texto.split("/")[0];
  texto = texto.split("?")[0];
  texto = texto.split("#")[0];
  texto = texto.split(":")[0];

  return texto;
}


// ============================================================
// 3. DETECTAR ALERTAS / FRAUDE
// ============================================================

function esAlerta(titulo, contenido, url) {

  const t = normalizar(
    `${titulo} ${contenido} ${url}`
  );

  const señales = [
    "alerta",
    "estafa",
    "estafas",
    "fraude",
    "fraud",
    "phishing",
    "suplantacion",
    "oferta falsa",
    "ofertas falsas",
    "oferta laboral falsa",
    "ofertas laborales falsas",
    "numero falso",
    "mensajes falsos",
    "no solicita pagos",
    "no solicita transferencias",
    "no realizar pagos",
    "cuidado"
  ];

  return señales.some(
    señal =>
      t.includes(normalizar(señal))
  );
}


// ============================================================
// 4. VALIDAR EMPRESA
// ============================================================

function tieneEmpresa(texto) {

  const t = normalizar(texto);

  return (
    t.includes("corporacion favorita") ||
    t.includes("corporacion favorita c.a") ||
    t.includes("corporacion favorita ca")
  );
}


// ============================================================
// 5. VALIDAR ÁREA RRHH
// ============================================================

function tieneRRHH(texto) {

  const t = normalizar(texto);

  const palabras = [
    "talento humano",
    "recursos humanos",
    "rrhh",
    "human resources",
    "people",
    "seleccion",
    "selección",
    "talent acquisition",
    "reclutamiento"
  ];

  return palabras.some(
    palabra =>
      t.includes(normalizar(palabra))
  );
}


// ============================================================
// 6. IDENTIFICAR PERFIL PERSONAL LINKEDIN
// ============================================================

function esPerfilLinkedInPersonal(url) {

  const u = normalizar(url);

  return (
    u.includes("linkedin.com/in/") ||
    u.includes("ec.linkedin.com/in/")
  );
}


// ============================================================
// 7. EXTRAER NOMBRE DESDE TÍTULO LINKEDIN
//
// Ejemplos:
// Eva Crespo - Sub Jefe...
// Gitta Bajana - Corporacion Favorita...
// ============================================================

function nombreDesdeTituloLinkedIn(titulo, url) {

  if (!esPerfilLinkedInPersonal(url)) {
    return "NO ENCONTRADO";
  }

  const tituloLimpio =
    limpiar(titulo);

  const primeraParte =
    tituloLimpio.split(" - ")[0].trim();

  if (!primeraParte) {
    return "NO ENCONTRADO";
  }

  const palabras =
    primeraParte.split(/\s+/);

  if (
    palabras.length < 2 ||
    palabras.length > 5
  ) {
    return "NO ENCONTRADO";
  }

  const prohibidos = [
    "corporacion favorita",
    "corporación favorita",
    "linkedin",
    "contacto",
    "empleos",
    "trabajo"
  ];

  const comparacion =
    normalizar(primeraParte);

  if (
    prohibidos.some(
      p => comparacion.includes(normalizar(p))
    )
  ) {
    return "NO ENCONTRADO";
  }

  return primeraParte;
}


// ============================================================
// 8. EXTRAER PERSONA DESDE CONTENIDO
//
// Ejemplo:
// Diana Terán,. Sub Jefe de talento Humano
// ============================================================

function nombreDesdeContenido(texto) {

  const limpio =
    limpiar(texto);

  const patrones = [

    /([A-ZÁÉÍÓÚÑ][A-Za-zÁÉÍÓÚáéíóúñÑ'-]+(?:\s+[A-ZÁÉÍÓÚÑ][A-Za-zÁÉÍÓÚáéíóúñÑ'-]+){1,3})\s*,?\.?\s*(?:Sub\s+Jefe|Sub\s+Jefa|Jefe|Jefa|Gerente|Director|Directora|Coordinador|Coordinadora)\s+de\s+(?:Talento\s+Humano|Recursos\s+Humanos)/i

  ];

  for (const regex of patrones) {

    const match =
      limpio.match(regex);

    if (
      match &&
      match[1]
    ) {
      return limpiar(match[1]);
    }
  }

  return "NO ENCONTRADO";
}


// ============================================================
// 9. EXTRAER CARGO
// ============================================================

function extraerCargo(texto) {

  const limpio =
    limpiar(texto);

  const patrones = [

    /Sub\s+Jefe\s+de\s+Talento\s+Humano(?:,\s*Zona\s+[A-Za-zÁÉÍÓÚáéíóúñÑ]+)?/i,

    /Sub\s+Jefa\s+de\s+Talento\s+Humano(?:,\s*Zona\s+[A-Za-zÁÉÍÓÚáéíóúñÑ]+)?/i,

    /Jefe\s+Corporativo\s+de\s+Talento\s+Humano/i,

    /Jefa\s+Corporativa\s+de\s+Talento\s+Humano/i,

    /Jefe\s+de\s+Talento\s+Humano/i,

    /Jefa\s+de\s+Talento\s+Humano/i,

    /Gerente\s+de\s+Talento\s+Humano/i,

    /Gerente\s+de\s+Recursos\s+Humanos/i,

    /Director\s+de\s+Talento\s+Humano/i,

    /Directora\s+de\s+Talento\s+Humano/i,

    /Director\s+de\s+Recursos\s+Humanos/i,

    /Directora\s+de\s+Recursos\s+Humanos/i,

    /Coordinador\s+de\s+Talento\s+Humano/i,

    /Coordinadora\s+de\s+Talento\s+Humano/i,

    /Coordinador\s+de\s+Recursos\s+Humanos/i,

    /Coordinadora\s+de\s+Recursos\s+Humanos/i,

    /Analista\s+de\s+Talento\s+Humano/i,

    /Analista\s+de\s+Recursos\s+Humanos/i

  ];

  for (const regex of patrones) {

    const match =
      limpio.match(regex);

    if (match) {
      return limpiar(match[0]);
    }
  }

  return "NO IDENTIFICADO";
}


// ============================================================
// 10. CLASIFICAR TIPO DE FUENTE
// ============================================================

function tipoFuente(url, dominio) {

  if (
    esPerfilLinkedInPersonal(url)
  ) {
    return "LINKEDIN_PERSONAL";
  }

  if (
    dominio === "corporacionfavorita.com"
  ) {
    return "WEB_CORPORATIVA";
  }

  if (
    dominio.includes("maxionline.ec")
  ) {
    return "FUENTE_RELACIONADA_EMPRESA";
  }

  if (
    dominio.includes("facebook.com") ||
    dominio.includes("instagram.com")
  ) {
    return "RED_SOCIAL";
  }

  return "FUENTE_PUBLICA_EXTERNA";
}


// ============================================================
// 11. ANALIZAR RESULTADOS
// ============================================================

const candidatos = [];
const descartados = [];

for (
  let i = 0;
  i < resultados.length;
  i++
) {

  const r =
    resultados[i] || {};

  const titulo =
    limpiar(r.title);

  const contenido =
    limpiar(r.content);

  const url =
    limpiar(r.url);

  const dominio =
    dominioDe(url);

  const textoCompleto =
    `${titulo} ${contenido}`;

  // ----------------------------------------------------------
  // ALERTAS / FRAUDE
  // ----------------------------------------------------------

  if (
    esAlerta(
      titulo,
      contenido,
      url
    )
  ) {

    descartados.push({

      ranking_original:
        i + 1,

      titulo,

      url,

      dominio,

      motivo:
        "ALERTA_O_POSIBLE_ESTAFA"

    });

    continue;
  }


  // ----------------------------------------------------------
  // VALIDACIÓN CONTEXTUAL
  // ----------------------------------------------------------

  const relacionEmpresa =
    tieneEmpresa(textoCompleto);

  const relacionRRHH =
    tieneRRHH(textoCompleto);

  if (!relacionEmpresa) {
    continue;
  }

  // Para candidatos RRHH exigimos evidencia explícita
  // del área correspondiente.
  if (!relacionRRHH) {
    continue;
  }


  // ----------------------------------------------------------
  // PERSONA
  // ----------------------------------------------------------

  let persona =
    nombreDesdeTituloLinkedIn(
      titulo,
      url
    );

  if (
    persona ===
    "NO ENCONTRADO"
  ) {

    persona =
      nombreDesdeContenido(
        textoCompleto
      );
  }


  // ----------------------------------------------------------
  // CARGO
  // ----------------------------------------------------------

  const cargo =
    extraerCargo(
      textoCompleto
    );


  // ----------------------------------------------------------
  // TIPO FUENTE
  // ----------------------------------------------------------

  const fuenteTipo =
    tipoFuente(
      url,
      dominio
    );


  // ----------------------------------------------------------
  // PUNTUACIÓN
  // ----------------------------------------------------------

  let puntuacion = 0;

  const razones = [];


  if (relacionEmpresa) {

    puntuacion += 30;

    razones.push(
      "EMPRESA_COINCIDE"
    );
  }


  if (relacionRRHH) {

    puntuacion += 35;

    razones.push(
      "AREA_RRHH_COINCIDE"
    );
  }


  if (
    esPerfilLinkedInPersonal(url)
  ) {

    puntuacion += 40;

    razones.push(
      "PERFIL_LINKEDIN_PERSONAL"
    );
  }


  if (
    persona !==
    "NO ENCONTRADO"
  ) {

    puntuacion += 30;

    razones.push(
      "PERSONA_IDENTIFICADA"
    );
  }


  if (
    cargo !==
    "NO IDENTIFICADO"
  ) {

    puntuacion += 35;

    razones.push(
      "CARGO_RRHH_IDENTIFICADO"
    );
  }


  if (
    dominio ===
    "corporacionfavorita.com"
  ) {

    puntuacion += 25;

    razones.push(
      "DOMINIO_CORPORATIVO"
    );
  }


  if (
    dominio.includes(
      "maxionline.ec"
    )
  ) {

    puntuacion += 20;

    razones.push(
      "FUENTE_RELACIONADA_EMPRESA"
    );
  }


  // ----------------------------------------------------------
  // NIVEL DE CONFIANZA
  // ----------------------------------------------------------

  let confianza =
    "BAJA";

  if (
    puntuacion >= 130 &&
    persona !== "NO ENCONTRADO" &&
    cargo !== "NO IDENTIFICADO"
  ) {

    confianza =
      "ALTA";

  } else if (
    puntuacion >= 85
  ) {

    confianza =
      "MEDIA";
  }


  // ----------------------------------------------------------
  // GUARDAR CANDIDATO
  // ----------------------------------------------------------

  candidatos.push({

    persona_contacto:
      persona,

    cargo_contacto:
      cargo,

    empresa,

    fuente_url:
      url,

    fuente_dominio:
      dominio,

    tipo_fuente:
      fuenteTipo,

    titulo_fuente:
      titulo,

    evidencia:
      contenido,

    puntuacion,

    confianza,

    razones,

    requiere_verificacion:
      true

  });
}


// ============================================================
// 12. ORDENAR POR PUNTUACIÓN
// ============================================================

candidatos.sort(
  (a, b) =>
    b.puntuacion -
    a.puntuacion
);


// ============================================================
// 13. DEDUPLICAR
// ============================================================

const vistos =
  new Set();

const candidatosUnicos =
  candidatos.filter(c => {

    const persona =
      normalizar(
        c.persona_contacto
      );

    let clave;

    if (
      persona !==
      normalizar(
        "NO ENCONTRADO"
      )
    ) {

      clave =
        `PERSONA:${persona}`;

    } else {

      clave =
        `SIN_PERSONA:${normalizar(
          c.cargo_contacto
        )}|${c.fuente_dominio}`;
    }

    if (
      vistos.has(clave)
    ) {
      return false;
    }

    vistos.add(clave);

    return true;
  });


// ============================================================
// 14. MEJOR CANDIDATO
// ============================================================

const mejor =
  candidatosUnicos.length > 0
    ? candidatosUnicos[0]
    : null;


// ============================================================
// 15. RESULTADO FINAL
// ============================================================

return [
  {
    json: {

      empresa,

