// ============================================================
// FUNCIONES GENERALES
// ============================================================

function limpiar(texto) {
  return String(texto || "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizar(texto) {
  return limpiar(texto)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

function dominioDe(url) {
  let texto = String(url || "")
    .trim()
    .toLowerCase();

  texto = texto
    .replace(/^https?:\/\//, "")
    .replace(/^www\./, "");

  return texto
    .split("/")[0]
    .split("?")[0]
    .split("#")[0]
    .split(":")[0];
}

function contiene(texto, valor) {
  return normalizar(texto)
    .includes(normalizar(valor));
}


// ============================================================
// FUENTES
// ============================================================

function esLinkedInPersonal(url) {
  const u = normalizar(url);

  return u.includes("linkedin.com/in/");
}

function esLinkedInEmpresa(url) {
  const u = normalizar(url);

  return (
    u.includes("linkedin.com/company/corporacionfavorita") ||
    u.includes("linkedin.com/company/corporacion-favorita")
  );
}

function esWebCorporativa(url) {
  return dominioDe(url) === "corporacionfavorita.com";
}

function esFuenteRelacionada(url) {
  return dominioDe(url).includes("maxionline.ec");
}

function nivelFuente(url) {

  if (esLinkedInPersonal(url)) {
    return 100;
  }

  if (esWebCorporativa(url)) {
    return 95;
  }

  if (esLinkedInEmpresa(url)) {
    return 90;
  }

  if (esFuenteRelacionada(url)) {
    return 80;
  }

  return 50;
}

function tipoFuente(url) {

  if (esLinkedInPersonal(url)) {
    return "LINKEDIN_PERSONAL";
  }

  if (esWebCorporativa(url)) {
    return "WEB_OFICIAL_EMPRESA";
  }

  if (esLinkedInEmpresa(url)) {
    return "LINKEDIN_OFICIAL_EMPRESA";
  }

  if (esFuenteRelacionada(url)) {
    return "FUENTE_RELACIONADA_EMPRESA";
  }

  return "FUENTE_PUBLICA_EXTERNA";
}


// ============================================================
// FRAUDE / EMPRESA INCORRECTA
// ============================================================

function esEmpresaIncorrecta(texto, url) {

  const t =
    normalizar(`${texto} ${url}`);

  return (
    t.includes("favoritabananas") ||
    t.includes("favoritafc.com")
  );
}

function esAlertaFraude(texto) {

  const t = normalizar(texto);

  const señales = [
    "estafa",
    "fraude",
    "fraudulenta",
    "oferta falsa",
    "ofertas falsas",
    "oferta laboral falsa",
    "ofertas laborales falsas",
    "phishing",
    "suplantacion",
    "cuidado"
  ];

  return señales.some(
    s => t.includes(normalizar(s))
  );
}


// ============================================================
// RRHH
// ============================================================

function tieneRRHH(texto) {

  const t = normalizar(texto);

  const palabras = [
    "talento humano",
    "recursos humanos",
    "rrhh",
    "tthh",
    "human resources",
    "people",
    "talent acquisition",
    "reclutamiento",
    "seleccion",
    "selección"
  ];

  return palabras.some(
    p => t.includes(normalizar(p))
  );
}


// ============================================================
// CARGOS
// ============================================================

function extraerCargo(texto) {

  const limpio = limpiar(texto);

  const patrones = [

    /Gerente\s+de\s+Recursos\s+Humanos/i,
    /Gerente\s+de\s+Talento\s+Humano/i,

    /Jefe\s+Corporativo\s+de\s+Talento\s+Humano/i,
    /Jefa\s+Corporativa\s+de\s+Talento\s+Humano/i,

    /Jefe\s+de\s+Talento\s+Humano/i,
    /Jefa\s+de\s+Talento\s+Humano/i,

    /Jefe\s+de\s+TTHH/i,
    /Jefa\s+de\s+TTHH/i,

    /Sub\s+Jefe\s+de\s+Talento\s+Humano(?:,\s*Zona\s+[A-Za-zÁÉÍÓÚáéíóúñÑ]+)?/i,
    /Sub\s+Jefa\s+de\s+Talento\s+Humano(?:,\s*Zona\s+[A-Za-zÁÉÍÓÚáéíóúñÑ]+)?/i,

    /Asistente\s+de\s+Talento\s+Humano/i,

    /Coordinador\s+de\s+Talento\s+Humano/i,
    /Coordinadora\s+de\s+Talento\s+Humano/i,

    /Analista\s+de\s+Talento\s+Humano/i,
    /Analista\s+de\s+Recursos\s+Humanos/i
  ];

  for (const regex of patrones) {

    const match = limpio.match(regex);

    if (match) {
      return limpiar(match[0]);
    }
  }

  return "NO IDENTIFICADO";
}


// ============================================================
// PERSONAS
// ============================================================

function personaDesdeLinkedIn(titulo, url) {

  if (!esLinkedInPersonal(url)) {
    return "NO ENCONTRADO";
  }

  const primera =
    limpiar(titulo)
      .split(" - ")[0]
      .trim();

  if (!primera) {
    return "NO ENCONTRADO";
  }

  const palabras = primera.split(/\s+/);

  if (
    palabras.length < 2 ||
    palabras.length > 6
  ) {
    return "NO ENCONTRADO";
  }

  return primera
    .replace(/\.$/, "")
    .trim();
}


function personaDesdeRocketReach(titulo) {

  const t = limpiar(titulo);

  let match = t.match(
    /(?:correo electrónico y teléfono de|correo electronico y telefono de)\s+([^|]+)\s*\|/i
  );

  if (match && match[1]) {
    return limpiar(match[1]);
  }

  match = t.match(
    /^([^|]+?)\s+Email\s*&\s*Phone/i
  );

  if (match && match[1]) {
    return limpiar(match[1]);
  }

  return "NO ENCONTRADO";
}


function personaDesdeZoomInfo(titulo) {

  const t = limpiar(titulo);

  const match = t.match(
    /^Contact\s+([^,]+),/i
  );

  if (match && match[1]) {
    return limpiar(match[1]);
  }

  return "NO ENCONTRADO";
}


function extraerOtraPersona(titulo, url) {

  let persona =
    personaDesdeLinkedIn(titulo, url);

  if (persona !== "NO ENCONTRADO") {
    return persona;
  }

  persona =
    personaDesdeRocketReach(titulo);

  if (persona !== "NO ENCONTRADO") {
    return persona;
  }

  persona =
    personaDesdeZoomInfo(titulo);

  return persona;
}


// ============================================================
// EMAILS
// ============================================================

function extraerEmails(texto) {

  const matches =
    String(texto || "").match(
      /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi
    ) || [];

  return [
    ...new Set(
      matches.map(x => x.toLowerCase())
    )
  ];
}

function tieneEmailEnmascarado(texto) {

  return (
    /[a-z0-9]\*{2,}@[a-z0-9.-]+\.[a-z]{2,}/i.test(texto) ||
    /\*+@[a-z0-9.-]+\.[a-z]{2,}/i.test(texto)
  );
}


// ============================================================
// TELÉFONOS ECUADOR
// ============================================================

function extraerTelefonos(texto) {

  const encontrados = [];

  const bruto = String(texto || "");

  const patrones = [

    /\+593[\s-]?\d{1,2}[\s-]?\d{3}[\s-]?\d{4,6}/g,

    /\b09\d{8}\b/g,

    /\b1800[\s-]?\d{3}[\s-]?\d{3}\b/g
  ];

  for (const regex of patrones) {

    const matches =
      bruto.match(regex) || [];

    for (const numero of matches) {

      encontrados.push(
        numero.replace(/[^\d+]/g, "")
      );
    }
  }

  return [...new Set(encontrados)];
}


// ============================================================
// DEDUPLICAR
// ============================================================

function deduplicar(lista, claveFn) {

  const vistos = new Set();

  return lista.filter(item => {

    const clave =
      normalizar(claveFn(item));

    if (!clave || vistos.has(clave)) {
      return false;
    }

    vistos.add(clave);

    return true;
  });
}


