const items = $input.all();


// ============================================================
// FUNCIONES
// ============================================================

function limpiar(texto) {
  return String(texto || "")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizar(texto) {
  return limpiar(texto)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}


// ============================================================
// PERSONAS YA INVESTIGADAS
// ============================================================

const yaInvestigadas = new Set();

for (const item of items) {

  const persona =
    normalizar(
      item.json.persona_contacto
    );

  if (persona) {
    yaInvestigadas.add(persona);
  }
}


// ============================================================
// RECOPILAR NUEVOS CANDIDATOS
// ============================================================

const candidatos = [];

for (const item of items) {

  const nuevos =
    Array.isArray(
      item.json.nuevos_candidatos_rrhh
    )
      ? item.json.nuevos_candidatos_rrhh
      : [];

  for (const candidato of nuevos) {

    const persona =
      limpiar(
        candidato.persona_contacto
      );

    const personaNorm =
      normalizar(persona);

    if (
      !persona ||
      persona === "NO ENCONTRADO"
    ) {
      continue;
    }


    // Evitar volver a investigar
    // Eva o Diana
    if (
      yaInvestigadas.has(
        personaNorm
      )
    ) {
      continue;
    }


    const cargo =
      limpiar(
        candidato.cargo_contacto
      ) || "NO IDENTIFICADO";


    // ========================================================
    // PUNTUACIÓN
    // ========================================================

    let puntuacion = 0;

    const razones = [];


    if (
      cargo !== "NO IDENTIFICADO"
    ) {

      puntuacion += 50;

      razones.push(
        "CARGO_RRHH_IDENTIFICADO"
      );
    }


    if (
      candidato.tipo_fuente ===
      "LINKEDIN_PERSONAL"
    ) {

      puntuacion += 40;

      razones.push(
        "PERFIL_LINKEDIN_PERSONAL"
      );
    }


    if (
      candidato.tipo_fuente ===
      "FUENTE_PUBLICA_EXTERNA"
    ) {

      puntuacion += 15;

      razones.push(
        "FUENTE_PUBLICA_EXTERNA"
      );
    }


    if (
      normalizar(
        candidato.evidencia
      ).includes(
        "corporacion favorita"
      )
    ) {

      puntuacion += 20;

      razones.push(
        "EMPRESA_COINCIDE"
      );
    }


    // ========================================================
    // CONSULTAS
    // ========================================================

    const consultaVerificacion =
      `"${persona}" "Corporación Favorita" ("Talento Humano" OR "Recursos Humanos" OR RRHH OR TTHH OR "Human Resources")`;


    const consultaContacto =
      `"${persona}" "Corporación Favorita" (email OR correo OR contacto OR telefono OR teléfono OR whatsapp)`;


    // ========================================================
    // PRIORIDAD
    // ========================================================

    let prioridad =
      "BAJA";

    if (
      puntuacion >= 70
    ) {

      prioridad =
        "ALTA";

    } else if (
      puntuacion >= 40
    ) {

      prioridad =
        "MEDIA";
    }


    candidatos.push({

      empresa:
        "Corporación Favorita",

      persona_contacto:
        persona,

      cargo_declarado:
        cargo,

      fuente_inicial:
        candidato.fuente_url,

      tipo_fuente_inicial:
        candidato.tipo_fuente,

      evidencia_inicial:
        candidato.evidencia,

      puntuacion_prioridad:
        puntuacion,

      prioridad_verificacion:
        prioridad,

      razones,

      consulta_verificacion:
        consultaVerificacion,

      consulta_contacto:
        consultaContacto,

      estado:
        "PENDIENTE_VERIFICACION_INDEPENDIENTE",

      reglas: {

        no_asumir_cargo:
          true,

        no_inventar_email:
          true,

        no_asumir_whatsapp:
          true,

        conservar_fuentes:
          true

      }

    });
  }
}


// ============================================================
// DEDUPLICAR PERSONAS
// ============================================================

const vistos =
  new Set();

const candidatosUnicos =
  candidatos.filter(c => {

    const clave =
      normalizar(
        c.persona_contacto
      );

    if (
      vistos.has(clave)
    ) {
      return false;
    }

    vistos.add(clave);

    return true;
  });


// ============================================================
// ORDENAR
// ============================================================

candidatosUnicos.sort(
  (a, b) =>
    b.puntuacion_prioridad -
    a.puntuacion_prioridad
);


// ============================================================
// ASIGNAR ORDEN
// ============================================================

const candidatosOrdenados =
  candidatosUnicos.map(
    (c, index) => ({

      orden_verificacion:
        index + 1,

      ...c

    })
  );


// ============================================================
// SALIDA
// ============================================================

return [
  {
    json: {

      empresa:
        "Corporación Favorita",

      estado:
        "NUEVOS_CANDIDATOS_PREPARADOS",

      total_nuevos_candidatos:
        candidatosOrdenados.length,

      candidatos_verificar:
        candidatosOrdenados,

      siguiente_accion:
        candidatosOrdenados.length > 0
          ? "BUSCAR_VERIFICACION_INDEPENDIENTE"
          : "NO_HAY_NUEVOS_CANDIDATOS"

    }
  }
];
